mapper.select:
SELECT a.path AS path, a.method AS method,
u.id AS userId, u.username AS username, p.id AS permissionId, p.name AS permissionName, p.code AS permissionCode, GROUP_CONCAT(DISTINCT r.id ORDER BY r.id SEPARATOR ',') AS roleIds, GROUP_CONCAT(DISTINCT r.name ORDER BY r.sort_order SEPARATOR ', ') AS roleNames, GROUP_CONCAT(DISTINCT r.code ORDER BY r.code SEPARATOR ',') AS roleCodes FROM sys_users u JOIN sys_user_roles ur ON u.id = ur.user_id AND ur.deleted = 0 JOIN sys_roles r ON ur.role_id = r.id AND r.deleted = 0 JOIN sys_role_permissions rp ON r.id = rp.role_id AND rp.deleted = 0 JOIN sys_permissions p ON rp.permission_id = p.id AND p.deleted = 0 JOIN sys_permission_apis pa ON p.id = pa.permission_id AND pa.deleted = 0 JOIN sys_apis a ON pa.api_id = a.id AND a.deleted = 0 AND a.enabled = 1
WHERE u.id = #{userId} AND u.deleted = 0 GROUP BY a.path, a.method, p.code, u.id, u.username ORDER BY a.path, a.method;
